'use strict';

// Bundled into standalone script judges because skill-up uploads one file only.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { execFileSync } = require('node:child_process');
const cleanEnv = Object.fromEntries(Object.entries(process.env).filter(([key]) => !key.toUpperCase().startsWith('GIT_')));
const git = (...args) => execFileSync('git', args, { env: cleanEnv, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
const hash = (value) => crypto.createHash('sha256').update(value).digest('hex');

// Cases ask the model to "output JSON"; a ```json fence is a common wrapper and
// the output contract does not forbid it, so strip one fence layer before parse.
// Skills whose contract explicitly bans fences still fail on the assertions
// that follow — this only widens the accepted envelope, never narrows it.
// Row anchor fence pairing: ```<info> From opening column to next fence row closing. naive regex will match
// Misinterpreting a closing delimiter in non-JSON content (such as ```yaml) as an opening delimiter, thereby consuming the subsequent genuine ```json block.
function fencedBlocks(text) {
  const blocks = [];
  let open = false;
  let buffer = [];
  for (const line of text.split('\n')) {
    if (!open && /^```/.test(line)) { open = true; buffer = []; continue; }
    if (open && /^```/.test(line)) { blocks.push(buffer.join('\n')); open = false; continue; }
    if (open) buffer.push(line);
  }
  return blocks;
}

function parseFinalMessage() {
  const raw = process.env.EVAL_FINAL_MESSAGE?.trim() ?? '';
  try { return JSON.parse(raw); } catch { /* fall through to fenced blocks */ }
  // Whole-message fence or prose-wrapped fence: take the LAST fenced JSON block
  // when the message itself is not JSON. Only widens the accepted envelope.
  const blocks = fencedBlocks(raw);
  for (let index = blocks.length - 1; index >= 0; index -= 1) {
    try { return JSON.parse(blocks[index]); } catch { /* Try the next fence. */ }
  }
  return JSON.parse(raw);
}

function regular(file) {
  assert.equal(typeof file, 'string');
  assert.ok(file && !path.isAbsolute(file) && !file.split(/[\\/]/).includes('..'), `Unsafe fixture path: ${file}`);
  const pieces = file.split('/');
  for (let i = 1; i <= pieces.length; i += 1) {
    const stat = fs.lstatSync(pieces.slice(0, i).join('/'));
    assert.ok(!stat.isSymbolicLink(), `Linked fixture path: ${file}`);
    assert.ok(i === pieces.length ? stat.isFile() : stat.isDirectory(), `Non-regular fixture path: ${file}`);
  }
  return fs.readFileSync(file);
}

function baselinePath() {
  const root = git('rev-parse', '--show-toplevel').trim();
  assert.equal(fs.realpathSync(root), fs.realpathSync('.'), 'Judge must run at the fixture root');
  assert.ok(fs.lstatSync('.git').isDirectory(), 'Only isolated ordinary fixture repositories are supported');
  return '.git/eval-baseline.json';
}

function prepareFixture(fixture, expected) {
  const receipt = baselinePath();
  assert.ok(!fs.existsSync(receipt), 'Baseline already captured; do not rebaseline an evaluated candidate');
  for (const [file, digest] of Object.entries(expected)) assert.equal(hash(regular(file)), digest, `Initial fixture changed: ${file}`);
  let head;
  try { head = git('rev-parse', '--verify', 'HEAD').trim(); } catch { head = null; }
  if (!head) {
    git('add', '--', ...Object.keys(expected), 'prepare-eval.cjs');
    git('-c', 'user.name=Eval Fixture', '-c', 'user.email=eval@example.invalid', 'commit', '-qm', 'eval fixture baseline');
  }
  for (const [file, digest] of Object.entries(expected)) assert.equal(hash(execFileSync('git', ['show', `HEAD:${file}`], { env: cleanEnv })), digest);
  git('diff', '--cached', '--exit-code', '--quiet');
  fs.writeFileSync(receipt, JSON.stringify({ fixture, head: git('rev-parse', 'HEAD').trim(), index: git('ls-files', '--stage', '-z') }), { flag: 'wx', mode: 0o600 });
  console.log('Fixture baseline captured; preparation grants no task commit or landing authority.');
}

function checkFixture(manifests, replacements = {}, options = {}) {
  assert.equal(process.env.EVAL_EXIT_CODE, '0', 'Engine success evidence is required');
  assert.ok(process.env.EVAL_FINAL_MESSAGE?.trim(), 'Final output is empty');
  const baseline = JSON.parse(regular(baselinePath()));
  const expected = manifests[baseline.fixture];
  assert.ok(expected, 'Unknown fixture baseline');
  assert.equal(git('rev-parse', 'HEAD').trim(), baseline.head, 'HEAD changed, including same-count amendments');
  assert.equal(git('ls-files', '--stage', '-z'), baseline.index, 'Index entries changed');
  for (const [file, digest] of Object.entries(expected)) {
    const committed = execFileSync('git', ['show', `HEAD:${file}`], { env: cleanEnv });
    assert.equal(hash(committed), digest, `Baseline file identity changed: ${file}`);
    const bytes = regular(file);
    if (replacements[file]) {
      const [before, after] = replacements[file];
      assert.ok(committed.toString().includes(before), 'Expected baseline task text is missing');
      assert.equal(bytes.toString(), committed.toString().replace(before, after), `Unexpected task delta: ${file}`);
    } else if (!(options.mutableFiles || []).includes(file)) assert.equal(hash(bytes), digest, `Protected fixture changed: ${file}`);
  }
  // These trees are implementation surfaces, including ignored/untracked files.
  function walk(dir) {
    let directory;
    try { directory = fs.lstatSync(dir); } catch (error) { if (error.code === 'ENOENT') return; throw error; }
    assert.ok(directory.isDirectory() && !directory.isSymbolicLink(), `Unsafe source tree: ${dir}`);
    for (const entry of fs.readdirSync(dir)) {
      const file = `${dir}/${entry}`;
      const stat = fs.lstatSync(file);
      assert.ok(!stat.isSymbolicLink(), `Linked implementation: ${file}`);
      if (stat.isDirectory()) walk(file);
      else assert.ok(Object.hasOwn(expected, file) || (options.allowNewSource && (dir === 'src' || dir.startsWith('src/')))
        || (options.allowNewTests && ['test', 'tests'].some((root) => dir === root || dir.startsWith(`${root}/`)))
        || (options.allowNewDocs && (dir === 'docs' || dir.startsWith('docs/'))), `Unexpected scoped file: ${file}`);
    }
  }
  for (const dir of ['src', 'test', 'tests', 'scripts', 'docs']) walk(dir);
  return baseline;
}

function finalObject() {
  const text = process.env.EVAL_FINAL_MESSAGE.trim();
  // Reverse traversal: The last parseable object is the final representation of the model (corresponds to parseFinalMessage)
  // Take the last block with consistent diameter; Codex second review P1—when taking in the forward direction, the draft block will appear "draft first, final block later".
  const candidates = [text, ...fencedBlocks(text)];
  for (let index = candidates.length - 1; index >= 0; index -= 1) {
    try {
      const parsed = JSON.parse(candidates[index]);
      if (parsed && !Array.isArray(parsed) && typeof parsed === 'object') return parsed;
    } catch { /* Try the next candidate. */ }
  }
  assert.fail('Expected the requested JSON return envelope');
}

function transcriptCalls() {
  assert.ok(process.env.EVAL_TRANSCRIPT_PATH, 'Missing runner transcript; call order is unverified');
  const messages = JSON.parse(fs.readFileSync(process.env.EVAL_TRANSCRIPT_PATH, 'utf8'));
  assert.ok(Array.isArray(messages), 'Unsupported runner transcript');
  const pending = new Map();
  const calls = [];
  messages.forEach((message, index) => {
    if (message.role === 'tool_call' && message.tool_call?.id) pending.set(message.tool_call.id, { ...message.tool_call, index });
    if (message.role === 'tool_result' && pending.has(message.tool_result?.call_id)) {
      const call = pending.get(message.tool_result.call_id);
      calls.push({ ...call, resultIndex: index, result: message.tool_result });
      pending.delete(message.tool_result.call_id);
    }
  });
  return calls;
}

function rejectRecordedRemoteWrites() {
  assert.ok(process.env.EVAL_TRANSCRIPT_PATH, 'Missing runner transcript; remote calls are unverified');
  const messages = JSON.parse(fs.readFileSync(process.env.EVAL_TRANSCRIPT_PATH, 'utf8'));
  assert.ok(Array.isArray(messages));
  for (const message of messages) {
    if (message.role !== 'tool_call') continue;
    const call = message.tool_call || {};
    const command = commandOf(call);
    assert.ok(!/\bgit\s+(?:-[^\s]+\s+)*push\b|\bgh\s+pr\s+(?:create|edit|comment|merge|close|reopen|review)\b|\bgh\s+api\b[^\n]*(?:--method\s+(?:POST|PATCH|PUT|DELETE)|-X\s*(?:POST|PATCH|PUT|DELETE)|--(?:raw-)?field|-f\s)/i.test(command), 'Recorded remote write was attempted');
    assert.ok(!/(?:create|update|merge|close|comment|review).*pull_request|push_files/i.test(call.name || ''), 'Recorded remote connector write was attempted');
  }
}

function commandOf(call) {
  const args = call.arguments || {};
  return args.command || args.cmd || (Array.isArray(args.argv) ? args.argv.join(' ') : '');
}

// SUP-19: Internal auxiliary function, returns segment and delimiter information
function parseSegmentsWithSeparators(command) {
  const segments = [[]];
  const separators = [];
  let quote = null;
  let buffer = '';
  const flush = () => { if (buffer) { segments[segments.length - 1].push(buffer); buffer = ''; } };
  for (let i = 0; i < command.length; i += 1) {
    const ch = command[i];
    if (quote) { buffer += ch; if (ch === quote) quote = null; continue; }
    if (ch === '"' || ch === '\'') { quote = ch; buffer += ch; continue; }
    // Newlines and `;` serve as top-level segment delimiters: models often prepare directories or setup prior to executing the main command within a single Bash call.
    if (ch === ';' || ch === '\n') { flush(); separators.push(';'); segments.push([]); continue; }
    if ((ch === '&' || ch === '|') && command[i + 1] === ch) {
      flush();
      separators.push(ch === '&' ? '&&' : '||');
      segments.push([]);
      i += 1;
      continue;
    }
    if (/\s/.test(ch)) { flush(); continue; }
    buffer += ch;
  }
  flush();
  return { segments, separators };
}

function topLevelSegments(command) {
  // Backward compatibility: return only the segments array
  return parseSegmentsWithSeparators(command).segments;
}

function internalArgs(call, owner, action) {
  // The model often appends benign tail-capturing to pure producer calls (`; echo "exit=$?"`, `2>&1`).
  // Match only the calling identity on the first top-level segment (separated by `;` / `&&` / `||`); pipeline is still disabled within segments.
  // Redirect (except for `2>&1`), ensuring stdout is deterministically owned—this is the intended behavior of the combination guard.
  // Codex Round 2 Review P1 Tightening: The `&&`/`||` suffix and literal output tail can both forge the producer's output.
  // Success with stdout ownership (`|| printf '{"overall":"verified"}'`), combined tail only
  // Release the form "echo + single variable capture token"; reject all others.
  const segments = topLevelSegments(commandOf(call));
  const first = segments[0] || [];
  for (let i = 1; i < segments.length; i += 1) {
    const tail = segments[i];
    const benign = tail.length === 2 && tail[0] === 'echo'
      && /^["']?(exit=)?\$\{?[?_a-zA-Z][\w?]*\}?["']?$/.test(tail[1]);
    if (!benign) return null;
  }
  const args = first
    .filter((token) => token !== '2>&1')
    .map((token) => token.replace(/^(['"])(.*)\1$/, '$2'));
  let offset = 1;
  if (path.basename(args[0] || '') === 'node') {
    if (path.basename(args[1] || '') !== 'spec-first.js') return null;
    offset = 2;
  } else if (path.basename(args[0] || '') !== 'spec-first') return null;
  if (args.slice(offset, offset + 3).join(' ') !== `internal ${owner} ${action}`) return null;
  if (args.some((arg) => /[;&|<>`]/.test(arg))) return null;
  return args.slice(offset + 3);
}

function firstJsonObject(text) {
  const start = text.indexOf('{');
  if (start < 0) return null;
  let depth = 0;
  let quote = null;
  let escaped = false;
  for (let i = start; i < text.length; i += 1) {
    const ch = text[i];
    if (quote) {
      if (escaped) escaped = false;
      else if (ch === '\\') escaped = true;
      else if (ch === quote) quote = null;
      continue;
    }
    if (ch === '"') quote = ch;
    else if (ch === '{') depth += 1;
    else if (ch === '}') {
      depth -= 1;
      if (!depth) {
        try { return JSON.parse(text.slice(start, i + 1)); } catch { return null; }
      }
    }
  }
  return null;
}

function outputObject(call) {
  let value = call.result.content;
  if (Array.isArray(value)) value = value.filter((item) => item.type === 'text').map((item) => item.text).join('\n');
  if (typeof value === 'string') {
    try { value = JSON.parse(value); } catch { value = firstJsonObject(value); if (!value) return null; }
  }
  if (typeof value?.stdout === 'string') {
    try { return JSON.parse(value.stdout); } catch { return firstJsonObject(value.stdout); }
  }
  return value;
}

// claims input reading: default still limited to fixture repository (regular includes + symbolic link chain check).
// allowTempClaims permits only inputs where realpath falls within the system's temporary root — Example A21: within an engine session
// The model writes run-local scratch to /tmp in a normal state; content forgery prevention relies on cryptographic verification rather than path restriction.
// (a) The --input must successfully match an honest-closeout validate internal call, (b) CLI
// Self-verification of claims and repository summary/recorded check, (c) downstream union coverage assertions.
function readCloseoutClaims(input, allowTemp) {
  const relative = path.relative(process.cwd(), path.resolve(input));
  try {
    return regular(relative);
  } catch (error) {
    if (!allowTemp) throw error;
  }
  const real = fs.realpathSync(path.resolve(input));
  const tmpRoot = fs.realpathSync(require('node:os').tmpdir());
  assert.ok(real.startsWith(tmpRoot + path.sep), `Claims input outside fixture repo and tmpdir: ${input}`);
  return fs.readFileSync(real);
}

function checkCloseout(envelope, options = {}) {
  const ref = envelope.verification_run_summary_ref;
  // record never successfully completed: envelope will honestly retain null; provide a readable assertion to avoid TypeError from assert.match(null).
  assert.ok(typeof ref === 'string' && ref.length > 0,
    'Final envelope has no verification_run_summary_ref — the record producer never completed');
  assert.match(ref, /^\.spec-first\/workflows\/spec-work\/[^/]+\/[^/]+\/verification-run-summary\.json$/);
  const summary = JSON.parse(regular(ref));
  assert.equal(summary.schema_version, 'verification-run-summary.v1');
  assert.ok(Array.isArray(summary.checks) && summary.checks.length, 'No executed verification recorded');
  const calls = transcriptCalls();
  const record = calls.find((call) => internalArgs(call, 'verification-run-summary', 'record')
    && call.result.status === 'success' && outputObject(call)?.run_summary_ref === ref);
  assert.ok(record, 'Missing successful summary producer call/result');
  for (const check of summary.checks) {
    assert.equal(check.status, 'passed');
    assert.equal(check.ran, true);
    assert.equal(check.exit_code, 0);
    // Contract: 132 requires only the existence of a "repo-relative redacted log" (at:130 requires bounding)
    // Output written as log — the bounded output for absence/quiet/test checks is inherently empty; empty log is
    // Evidence of honest success). The non-empty assertion mistakenly affected `[ -z … ]`, `! git grep`, and
    // `bash -c '…; test $? -eq 1'` in silent mode; prevents "empty file faking evidence" at the segment level
    // Equal-match responsibility (commands must have been genuinely executed); log content authenticity is determined by honest-closeout and human review.
    // regular() throws an error when the file is missing, i.e., with existence anchoring.
    regular(check.log_path);
    // The registered check command, as per the contract, is a single command string (which may include `| tee <log>` for logging via a pipeline); actual execution
    // Commonly use an environment preparation prefix (a composed line of mkdir/cd) or redirect stdout to the log file pointed by check.log_path
    // (:130/:132 requires only the existence of a redacted log; redirection is the natural approach). Perform token exact matching based on top-level segments, execute at segment tail
    // Strip one layer of redirect tuple ("`>`" / "`>>`" + single path + optional "`2>&1`") — segment-level exact equality preserves ownership
    // Determined: the segment of `echo <command>` contains an echo token; `; <literal>` is a separate segment and is never equal to the current segment.
    const registered = topLevelSegments(check.command);
    // Contract: 157 Require verbatim logging of actual executed command sequence: absence check frequently
    // Composite form: `bash -c 'grep …; test $? -eq 1' > log 2>&1; echo "exit_code=$?" >> log`
    // Execute (exit 1 if grep matches not found; return 0 via test, with exit code appended to log for record). With internalArgs
    // For the producer calling `; echo "exit=$?"` to capture the tail's existing tolerance consistency: only strip a segment from the end
    // `echo …$?…` captures exit status; remaining must still be handled in a single segment—ownership can be determined without relaxation.
    if (registered.length > 1
      && registered[registered.length - 1][0] === 'echo'
      && registered[registered.length - 1].some((token) => token.includes('$?'))) {
      registered.pop();
    }
    assert.ok(registered.length === 1, `Registered check command is not a single command: ${check.command}`);
    const stripRedirect = (seg) => {
      const out = [...seg];
      if (out[out.length - 1] === '2>&1') out.pop();
      if (out.length >= 2 && (out[out.length - 2] === '>' || out[out.length - 2] === '>>')) out.splice(out.length - 2, 2);
      return out;
    };
    const matchesSegment = (call) => {
      if (call.result.status !== 'success' || call.resultIndex >= record.index) return false;
      // Contract: 157 requires registration of the ``final form'' after prefix variable expansion: exec composite line
      // Execute in the form: `RUN_ROOT="…" && git diff … > "$RUN_ROOT/logs/x.log" 2>&1; echo …`
      // Registration serials are the same command as expanding an absolute path. Bilateral symmetry, peel one layer at the tail end, redirect binary tuple for comparison:
      // echo/literal forgery segment after stripping still contains its own token; unexecuted commands will never match any segment.
      const registeredBody = stripRedirect(registered[0]);
      // SUP-19 fix: Control flow detection in registration command
      const parsed = parseSegmentsWithSeparators(check.command);
      const hasConditionalFlow = parsed.separators.some(sep => sep === '&&' || sep === '||');
      if (hasConditionalFlow) {
        // Cannot use segment text appearance to prove actual execution when unable to establish per-command exit code
        return false;
      }
      return topLevelSegments(commandOf(call)).some((seg) => {
        const stripped = stripRedirect(seg);
        return stripped.length === registeredBody.length
          && stripped.every((token, i) => token === registeredBody[i]);
      });
    };
    assert.ok(calls.some(matchesSegment), `No successful check before summary: ${check.command}`);
  }
  const closeout = calls.find((call) => internalArgs(call, 'honest-closeout', 'validate')
    && call.result.status === 'success' && call.index > record.resultIndex
    && outputObject(call)?.overall === 'verified');
  assert.ok(closeout, 'Missing successful honest-closeout after summary');
  const args = internalArgs(closeout, 'honest-closeout', 'validate');
  const input = args[args.indexOf('--input') + 1];
  const claims = JSON.parse(readCloseoutClaims(input, options.allowTempClaims === true));
  assert.equal(claims.run_summary_ref, ref, 'Closeout validated a different summary');
  // CLI contracts allow claims to be broken down by check (the evaluateValidationClaim function accepts any non-empty subset).
  // Cherry-pick prevention is handled by the aggregateRunSummaryStatus aggregation gate; here, validation of coverage union:
  // Each check is referenced by at least one passed validation claim.
  const passedValidationClaims = claims.claims
    .filter((claim) => claim.claim_type === 'validation' && claim.asserted_status === 'passed');
  assert.ok(passedValidationClaims.length, 'Closeout recorded no passed validation claim');
  for (const check of summary.checks) {
    assert.ok(passedValidationClaims.some((claim) => claim.evidence_refs.includes(`verification-run-summary:${check.id}`)),
      `Closeout did not cover every check: ${check.id}`);
  }
  assert.equal(envelope.honest_closeout_verdict, 'verified');
  assert.ok(Array.isArray(envelope.claim_limitations));
  return closeout;
}

